#include <string>
#include <unordered_map>
using namespace std;

class Solution {
public:
    int findTheLongestSubstring(string s) {
        unordered_map<int, int> seen;
        seen[0] = -1;
        int mask = 0, result = 0;

        for (int i = 0; i < s.size(); ++i) {
            if (s[i] == 'a') mask ^= 1;
            if (s[i] == 'e') mask ^= 2;
            if (s[i] == 'i') mask ^= 4;
            if (s[i] == 'o') mask ^= 8;
            if (s[i] == 'u') mask ^= 16;

            if (seen.count(mask)) result = max(result, i - seen[mask]);
            else seen[mask] = i;
        }

        return result;
    }
};
